  const helperAudits=(await pool.query<{count:number}>(`SELECT count(*)::int count FROM audit_events WHERE household_id=$1 AND action='ai.chatgpt_helper_prepared'`,[actor.household_id])).rows[0]!.count;await saturate('chatgpt_helper_account',actor.account_id,10);const helper=await app.inject({method:'POST',url:`/api/v1/households/${actor.household_id}/ai/chatgpt/helper`,headers:headers(session,csrf)});assert.equal(helper.statusCode,429,helper.body);assert.equal((await pool.query<{count:number}>(`SELECT count(*)::int count FROM audit_events WHERE household_id=$1 AND action='ai.chatgpt_helper_prepared'`,[actor.household_id])).rows[0]!.count,helperAudits);await pool.query(`DELETE FROM rate_limits WHERE bucket='chatgpt_helper_account' AND key_hash=$1`,[tokenHash(actor.account_id)]);
  const beforeConnections=(await pool.query<{count:number}>('SELECT count(*)::int count FROM calendar_connections WHERE household_id=$1',[actor.household_id])).rows[0]!.count;await saturate('calendar_connection_create_account',actor.account_id,12);const createBlocked=await app.inject({method:'POST',url:`/api/v1/households/${actor.household_id}/calendar-connections`,headers:headers(session,csrf),payload:{provider:'ics',name:'Must not be created',bridgeKind:'direct',icsUrl:'https://calendar.example/blocked.ics'}});assert.equal(createBlocked.statusCode,429,createBlocked.body);assert.equal((await pool.query<{count:number}>('SELECT count(*)::int count FROM calendar_connections WHERE household_id=$1',[actor.household_id])).rows[0]!.count,beforeConnections);await pool.query(`DELETE FROM rate_limits WHERE bucket='calendar_connection_create_account' AND key_hash=$1`,[tokenHash(actor.account_id)]);
  const setup=await app.inject({method:'POST',url:`/api/v1/households/${actor.household_id}/calendar-connections`,headers:headers(session,csrf),payload:{provider:'google',name:'Synthetic bounded OAuth',bridgeKind:'direct'}});assert.equal(setup.statusCode,201,setup.body);const setupId=setup.json().connection.id;await saturate('calendar_oauth_start_account',actor.account_id,20);const sessionsBefore=(await pool.query<{count:number}>('SELECT count(*)::int count FROM calendar_oauth_sessions')).rows[0]!.count;const oauthBlocked=await app.inject({method:'POST',url:`/api/v1/households/${actor.household_id}/calendar-connections/${setupId}/oauth/start`,headers:headers(session,csrf)});assert.equal(oauthBlocked.statusCode,429,oauthBlocked.body);assert.equal((await pool.query<{count:number}>('SELECT count(*)::int count FROM calendar_oauth_sessions')).rows[0]!.count,sessionsBefore);await pool.query(`DELETE FROM rate_limits WHERE bucket='calendar_oauth_start_account' AND key_hash=$1`,[tokenHash(actor.account_id)]);
  const activeCount=(await pool.query<{count:number}>(`SELECT count(*)::int count FROM calendar_connections WHERE household_id=$1 AND disconnected_at IS NULL`,[actor.household_id])).rows[0]!.count,capIntegrationIds:string[]=[];
  for(let index=activeCount;index<12;index++){const integration=(await pool.query<{id:string}>(`INSERT INTO integration_connections(household_id,name) VALUES($1,$2) RETURNING id`,[actor.household_id,`Synthetic cap ${index}`])).rows[0]!;capIntegrationIds.push(integration.id);await pool.query(`INSERT INTO calendar_connections(household_id,integration_connection_id,owner_account_id,provider,bridge_kind,name,state) VALUES($1,$2,$3,'google','direct',$4,'setup')`,[actor.household_id,integration.id,actor.account_id,`Synthetic cap ${index}`]);}
