  const buckets=(await pool.query<{bucket:string}>(`SELECT DISTINCT bucket FROM rate_limits WHERE bucket=ANY($1::text[])`,[['person_photo_upload_household','person_photo_upload_ip','chatgpt_helper_household','chatgpt_helper_ip','calendar_connection_create_household','calendar_connection_create_ip','calendar_oauth_start_household','calendar_oauth_start_ip','calendar_preview_household','calendar_preview_ip','calendar_manual_sync_household','calendar_manual_sync_ip']])).rows.map((row)=>row.bucket);assert.equal(buckets.length,12,'legitimate workflows populate account, household and IP durable buckets');
