  const task=(await pool.query<{id:string}>(`INSERT INTO monitor_tasks(household_id,owner_membership_id,name,instruction,source_url,state,check_interval_minutes,notice_days_before,notice_local_time,provider_policy,model_tier,interpreted_rule,revision,approved_revision) VALUES($1,$2,'Synthetic person task','Monitor a synthetic source only.','https://example.test.invalid/source','active',60,1,'18:00','default','routine','{}',2,2) RETURNING id`,[fixture.household_id,fixture.membership_id])).rows[0]!;
